const test   = require('node:test');
const assert = require('node:assert');
const { makeSandbox, fakeAnthropic } = require('./helpers');
const utils  = require('../src/utils');

// ─── Helpers ──────────────────────────────────────────────────────────────────

test('stripBotMention removes every mention of the bot, in both forms, and nothing else', () => {
    assert.strictEqual(utils.stripBotMention('<@123> how do I stake', '123'), 'how do I stake');
    assert.strictEqual(utils.stripBotMention('<@123> hi <@123> how?', '123'), 'hi  how?');
    assert.strictEqual(utils.stripBotMention('<@!123> hello', '123'), 'hello');
    assert.strictEqual(utils.stripBotMention('<@1234> other user', '123'), '<@1234> other user');
});

test('splitMessage keeps every chunk within the limit and loses no text', () => {
    const text = Array.from({ length: 300 }, (_, i) => `line ${i} of a long report`).join('\n');
    const chunks = utils.splitMessage(text, 2000);
    assert.ok(chunks.every(c => c.length <= 2000));
    assert.strictEqual(chunks.join(''), text);
});

test('looksResolved recognises "sorted" messages but not questions', () => {
    assert.ok(utils.looksResolved('ok fixed now'));
    assert.ok(!utils.looksResolved('how do I convert my points'));
});

test('getWeekRange covers Monday 00:00 to Sunday 23:59:59', () => {
    const { from, to } = utils.getWeekRange();
    assert.strictEqual(from.getDay(), 1);
    assert.strictEqual(to.getDay(), 0);
    assert.strictEqual(Math.round((to - from) / 86400000), 7);
});

// ─── Community reports ────────────────────────────────────────────────────────

test('community report: Telegram-only leaves out Discord tickets; Both includes them', async () => {
    const now = new Date().toISOString();
    const files = ['weekly-report/community-report/community-report.js', 'src/intent.js', 'src/utils.js', 'src/kb-sync.js', 'src/blog-scraper.js'];
    const box = makeSandbox(files, {
        'intent/ticket-log.jsonl': JSON.stringify({ ts: now, id: 't1', channelId: 'ticket-1', content: 'my withdrawal is stuck' }) + '\n',
        'intent/tg-intent-log.jsonl': JSON.stringify({ ts: now, id: 'g1', threadId: 1, content: 'when is S7 airdrop' }) + '\n',
        'intent/dc-intent-log.jsonl': JSON.stringify({ ts: now, id: 'd1', channelId: 'general', content: 'how to stake' }) + '\n',
    });
    try {
        const { buildCommunityReport } = require(box.path('weekly-report/community-report/community-report.js'));
        const prompts = [];
        const ai = fakeAnthropic((req) => { prompts.push(req.messages[0].content); return '**Common Problems**\n• x'; });
        const tg = await buildCommunityReport(ai, { GENERAL_CHANNEL_ID: 'general', SUPPORT_CHANNEL_ID: 'support', platform: 'telegram', reportType: 'daily', force: true });
        assert.strictEqual(tg.tickets.length, 0);
        assert.ok(!prompts[0].includes('Support Tickets'));
        const both = await buildCommunityReport(ai, { GENERAL_CHANNEL_ID: 'general', SUPPORT_CHANNEL_ID: 'support', platform: 'both', reportType: 'daily', force: true });
        assert.strictEqual(both.tickets.length, 1);
        assert.ok(prompts[1].includes('Support Tickets'));
    } finally { box.cleanup(); }
});

// ─── Linked tweets ────────────────────────────────────────────────────────────

test('tweet check: fake help desks, known campaigns, tweets with links, ordinary posts and unreadable tweets', async () => {
    const { createTweetChecker, isLinkOnly } = require('../src/tweet-check');
    const tweets = {
        1: { name: 'Support Desk', handle: 'supportdesk578', text: 'Share your questions here' },
        2: { name: 'Cristina', handle: 'celia', text: 'Relay your query HERE ⤵️ https://discord.gg/znEM' },
        3: { name: 'Bob', handle: 'bob', text: 'New article https://news.example/river' },
        4: { name: 'NHK', handle: 'langtusg0308', text: 'Shit project ! https://pic.x.com/abc' },
        5: { name: 'Faizan', handle: 'muha30316', text: '@RiverdotInc Argentina 1-0' },
        6: { name: 'River', handle: 'RiverdotInc', text: 'Join our community https://discord.com/invite/river-inc' },
        7: { name: 'Fan', handle: 'fan', text: 'Official server: https://discord.com/invite/river-inc' },
    };
    const checker = createTweetChecker({ fetchTweet: async (id) => tweets[id] ?? { error: 'NOT_FOUND' }, retryDelaysMs: [] });
    const verdict = async (text, campaign) => (await checker.check(text, campaign))?.verdict ?? null;
    assert.strictEqual(await verdict('https://x.com/supportdesk578/status/1'), 'scam', 'support/ticket account name');
    assert.strictEqual(await verdict('https://x.com/i/status/2'), 'scam', 'Discord invite in the tweet');
    assert.strictEqual(await verdict('https://x.com/i/status/9', new Map([['9', 2]])), 'scam', 'tweet already posted by 2+ actioned accounts');
    assert.strictEqual(await verdict('https://x.com/i/status/9', new Map([['9', 1]])), 'unavailable', 'one earlier poster is not a campaign');
    assert.strictEqual((await checker.check('https://x.com/supportdesk578/status/8')).deskHandle, 'supportdesk578', 'unreadable, but the link names a fake help desk');
    assert.strictEqual((await checker.check('https://x.com/i/status/8')).deskHandle, null, 'no account name in the link');
    assert.strictEqual(await verdict('https://x.com/bob/status/3'), 'has-link', 'other links are left to the classifier');
    assert.strictEqual(await verdict('https://x.com/langtusg0308/status/4'), 'ordinary', "the tweet's own image link doesn't count");
    assert.strictEqual(await verdict('https://twitter.com/muha30316/status/5?s=46'), 'ordinary');
    assert.strictEqual(await verdict('https://x.com/RiverdotInc/status/6'), 'ordinary', "River's own account sharing its own server is an ordinary post");
    assert.strictEqual(await verdict('https://x.com/RiverdotInc/status/6', new Map([['6', 5]])), 'ordinary', "River's own tweet is never a known campaign, even after wrong actions");
    assert.strictEqual(await verdict('https://x.com/fan/status/7'), 'ordinary', "River's official invite is not a fake help-desk invite or an outside link");
    assert.strictEqual(await verdict('no tweet here'), null);
    assert.strictEqual(isLinkOnly('https://x.com/i/status/1 ─ ✦ ─ <@123>'), true);
    assert.strictEqual(isLinkOnly('River https://x.com/i/status/1'), true);
    assert.strictEqual(isLinkOnly('**Please move this discussion to the appropriate board.** https://x.com/i/status/1'), false);
});

test('official links: River\'s own links are recognised exactly, and never trigger the hard scam rules', () => {
    const { stripOfficialLinks } = require('../src/utils');
    const { detectScamContentSync } = require('../src/intent');
    const official = (link) => !stripOfficialLinks(link).trim();
    for (const link of ['Riverai.inc', 'https://riverai.inc/', 'https://docs.riverai.inc/outro/official-links', 'gov.riverai.inc', 'https://t.me/river_inc', 'https://t.me/river_inc/1/', 't.me/river_inc/12345', 'https://discord.com/invite/river-inc', 'https://x.com/riverdotinc', 'https://github.com/Satoshi-Protocol']) {
        assert.ok(official(link), `official: ${link}`);
    }
    for (const link of ['https://riverai.inc.help-desk.xyz/ticket', 'fakeriverai.inc', 'riverai-inc.com', 'https://riverai.incs.com', 't.me/river_inc_support', 'discord.gg/river-inc2', 'x.com/riverdotinc_help', 'https://github.com/Satoshi-Protocol-fake']) {
        assert.ok(!official(link), `not official: ${link}`);
    }
    assert.strictEqual(detectScamContentSync('Join us at https://t.me/river_inc'), false);
    assert.strictEqual(detectScamContentSync('ask in the topic https://t.me/river_inc/1/'), false, 'a topic in the official group');
    assert.strictEqual(detectScamContentSync('report your issue to the team https://riverai.inc'), false);
    assert.strictEqual(detectScamContentSync('Join us at https://t.me/river_inc_help'), true, 'a lookalike is still caught');
    assert.strictEqual(detectScamContentSync('report your issue to the team https://riverai.inc.help-desk.xyz'), true, 'a lookalike domain is still caught');
    assert.strictEqual(detectScamContentSync('see riverai.inc or join t.me/fakehelp'), true, 'an official link beside a scam link changes nothing');
});

test('Telegram: deleted messages are dropped from a batch before it is answered', async () => {
    const { existingMessages } = require('../telegram/telegram-adapter');
    const answers = {
        1: new Error('400: Bad Request: REACTION_EMPTY'),                    // what an existing message answers
        2: new Error('400: Bad Request: message to react not found'),        // what a deleted message answers
        3: null,                                                             // success: also still there
        4: new Error('network down'),                                        // unknown: never drop a question over this
    };
    const seen = [];
    const telegram = { setMessageReaction: async (chat, id, reaction) => { seen.push([chat, id, reaction]); if (answers[id]) throw answers[id]; return true; } };
    const batch = [1, 2, 3, 4].map(n => ({ id: `tg_${n}`, content: `q${n}` }));
    assert.deepStrictEqual((await existingMessages(telegram, -100, batch)).map(m => m.id), ['tg_1', 'tg_3', 'tg_4']);
    assert.deepStrictEqual(seen[0], [-100, 1, []], 'the check only clears the bot\'s own reaction');
    assert.deepStrictEqual(await existingMessages(telegram, -100, [batch[1]]), [], 'nothing left: the batch is skipped');
});

test('tweet check: a failed read is retried, and a failure is never remembered', async () => {
    const { createTweetChecker } = require('../src/tweet-check');
    const good = { name: 'Support Desk', handle: 'desk', text: 'Create a ticket https://discord.gg/abc' };
    const answers = [{ error: 'HTTP 500' }, new Error('timeout'), good];
    let calls = 0;
    const flaky = createTweetChecker({
        fetchTweet: async () => { const a = answers[calls++]; if (a instanceof Error) throw a; return a; },
        retryDelaysMs: [0, 0],
    });
    assert.strictEqual((await flaky.check('https://x.com/i/status/1')).verdict, 'scam', 'the third attempt reads the tweet');
    assert.strictEqual(calls, 3);
    await flaky.check('https://x.com/i/status/1');
    assert.strictEqual(calls, 3, 'a tweet that was read is reused');

    let failing = 0;
    const down = createTweetChecker({
        fetchTweet: async () => (++failing > 3 ? good : { error: 'HTTP 503' }),
        retryDelaysMs: [0, 0],
    });
    assert.strictEqual((await down.check('https://x.com/i/status/2')).verdict, 'unavailable', 'every attempt failed');
    assert.strictEqual(failing, 3, 'three attempts');
    assert.strictEqual((await down.check('https://x.com/i/status/2')).verdict, 'scam', 'the next message reads it again');
});

test('scam check: asking staff to check DMs is let through, even with a member alongside; asking only members follows the DM rules', async () => {
    const { createIntentModule } = require('../src/intent');
    // The focused scam check always says YES; the classifier says staff-ping.
    const anthropic = fakeAnthropic((req) => (String(req.system).startsWith('You are a scam detection') ? 'YES' : 'staff-ping'));
    const intent = createIntentModule(anthropic, {
        SUPPORT_CHANNEL_ID: 'support', isStaffUser: async (_guild, id) => id.startsWith('staff'),
    });
    const user = (id) => ({ id, username: id, bot: false });
    const msg = ({ replyTo = null, mentions = [] } = {}) => ({
        id: 'm1', channelId: 'general', guild: {}, member: null, author: user('sender'),
        reference: replyTo ? { messageId: 'r1' } : null,
        mentions: { users: new Map(mentions.map(id => [id, user(id)])) },
        channel: { messages: { fetch: async (q) => (typeof q === 'string' ? { author: user(replyTo), content: 'hi' } : new Map()) } },
    });
    const scamChecks = () => anthropic.calls.filter(c => String(c.system).startsWith('You are a scam detection')).length;

    assert.strictEqual(await intent.classifyMessageIntent('mod please check dm', msg({ replyTo: 'staff1' })), 'staff-ping', 'reply to a mod');
    assert.strictEqual(await intent.classifyMessageIntent('<@staff1> check my dm', msg({ mentions: ['staff1'] })), 'staff-ping', 'tagging a mod');
    assert.strictEqual(scamChecks(), 0, 'no scam check for a request aimed at staff');
    assert.match(anthropic.calls.at(-1).messages[0].content, /STAFF member/, 'the classifier is told the person is staff');

    assert.strictEqual(await intent.classifyMessageIntent('check dm', msg({ replyTo: 'member1' })), 'scam-content', 'reply to a member');
    assert.strictEqual(await intent.classifyMessageIntent('check dm <@member1>', msg({ mentions: ['member1'] })), 'scam-content', 'tagging a member');
    assert.strictEqual(await intent.classifyMessageIntent('check dm <@staff1> <@member1>', msg({ mentions: ['staff1', 'member1'] })), 'staff-ping', 'a mod tagged alongside a member');
    assert.strictEqual(await intent.classifyMessageIntent('check dm', msg({ replyTo: 'member1', mentions: ['staff1'] })), 'staff-ping', 'reply to a member, tagging a mod');
    assert.strictEqual(await intent.classifyMessageIntent('check dm', msg({ replyTo: 'staff1' }), null, { matched: true, staffName: 'Mati' }), 'scam-content', 'a staff-like name still gets the check');
    assert.strictEqual(await intent.classifyMessageIntent('mod check dm t.me/fakehelp', msg({ replyTo: 'staff1' })), 'scam-content', 'hard rules still apply');
});
